class Design_Core_Agent_Semantic {
 protected $planner=null; public function __construct($planner=null){if($planner instanceof Design_Core_Elementor_Component_Planner)$this->planner=$planner;}
 public function component_ontology(array $input){$type=sanitize_key((string)($input['component_type']??''));if($type){$contract=Design_Core_Elementor_Component_Ontology::get($type);if(!$contract)return Design_Core_Agent_Contract::error('component_type','Unknown component type.',404);return array('status'=>'ok','ontology_version'=>Design_Core_Elementor_Component_Ontology::VERSION,'component_type'=>$type,'contract'=>$contract);}return array('status'=>'ok','ontology_version'=>Design_Core_Elementor_Component_Ontology::VERSION,'types'=>Design_Core_Elementor_Component_Ontology::types(),'contracts'=>Design_Core_Elementor_Component_Ontology::all());}
 public function component_plan(array $input){if(!$this->planner)$this->planner=new Design_Core_Elementor_Component_Planner();$r=$this->planner->plan($input);return is_wp_error($r)?Design_Core_Agent_Contract::error('component_plan',$r->get_error_message(),422):$r;}
 public function verify_preview(array $input){$components=(array)($input['components']??array());$elements=(array)($input['elements']??array());if(!$components||!$elements)return array('status'=>'fail','semantic_qa'=>'fail','issues'=>array(array('code'=>'semantic_input')));$flat=Design_Core_Agent_Knowledge::flatten_tree($elements);$by=array();foreach($flat as $row)$by[(string)$row['element_id']]=$row;$issues=array();$reports=array();$typed=0;$verified=0;foreach($components as $i=>$c){$type=sanitize_key((string)($c['component_type']??''));$impl=sanitize_key((string)($c['implementation_type']??''));$selected=sanitize_key((string)($c['selected_widget']??''));if(!$type||!$impl){$reports[]=array('index'=>$i,'status'=>'not_verified');continue;}$typed++;$contract=Design_Core_Elementor_Component_Ontology::get($type);if(!$contract){$issues[]=array('component_index'=>$i,'code'=>'component_type');continue;}$widgets=array();$has_container=false;foreach((array)($c['element_ids']??array()) as $id){if(!isset($by[(string)$id]))continue;$row=$by[(string)$id];if('container'===($row['element_type']??''))$has_container=true;if('widget'===($row['element_type']??''))$widgets[]=sanitize_key((string)($row['widget']??''));}$plan=$this->component_plan(array('component_type'=>$type,'behaviors'=>(array)($c['behaviors']??array()),'repeated'=>!empty($c['repeated']),'minimum_direct_score'=>isset($c['minimum_direct_score'])?(float)$c['minimum_direct_score']:.56,'limit'=>20));$ci=array();if('direct_widget'===$impl){$candidate=null;foreach((array)($plan['direct_candidates']??array()) as $row){if(($row['name']??'')===$selected){$candidate=$row;break;}}if(!$candidate||!in_array($selected,$widgets,true))$ci[]=array('code'=>'selected_widget_rejected');elseif(!empty($candidate['fit']['unverified_behaviors']))$ci[]=array('code'=>'behavior_unverified');}elseif('custom_native_widget'===$impl){$expected=sanitize_key((string)($contract['custom_widget']??''));if(!$expected||$selected!==$expected||!in_array($selected,$widgets,true))$ci[]=array('code'=>'custom_widget_mismatch');}elseif('native_composition'===$impl){if(empty($contract['native_composition']))$ci[]=array('code'=>'composition_not_defined');if(count($widgets)>1&&!$has_container)$ci[]=array('code'=>'composition_structure');if(in_array($type,array('navigation','jump-navigation','link-group'),true)&&$widgets&&!array_diff($widgets,array('button')))$ci[]=array('code'=>'button_navigation_cluster');if(in_array($type,array('process-steps','comparison-table','data-table'),true)&&count($widgets)===1&&'text-editor'===$widgets[0])$ci[]=array('code'=>'composite_text_editor');}else$ci[]=array('code'=>'implementation_type');foreach($ci as $issue){$issue['component_index']=$i;$issue['component_type']=$type;$issues[]=$issue;}if(!$ci)$verified++;$reports[]=array('index'=>$i,'component_type'=>$type,'implementation_type'=>$impl,'selected_widget'=>$selected,'referenced_widgets'=>array_values(array_unique($widgets)),'status'=>$ci?'fail':'pass','planner_recommendation'=>$plan['recommendation']??array());}$qa=$issues?'fail':($typed===count($components)&&$verified===$typed?'pass':'not_verified');$r=array('status'=>$qa==='fail'?'fail':'ok','semantic_qa'=>$qa,'planner_version'=>Design_Core_Elementor_Component_Planner::VERSION,'ontology_version'=>Design_Core_Elementor_Component_Ontology::VERSION,'component_count'=>count($components),'typed_component_count'=>$typed,'verified_component_count'=>$verified,'issues'=>$issues,'components'=>$reports);$r['evidence_hash']=Design_Core_Agent_Contract::hash($r);return $r;}
 public function bind_preview($preview_id,$artifact_hash,array $report){$record=array('owner'=>get_current_user_id(),'preview_id'=>(string)$preview_id,'artifact_hash'=>(string)$artifact_hash,'report'=>$report,'expires'=>time()+3600);$record['signature']=hash_hmac('sha256',Design_Core_Agent_Contract::json($record),wp_salt('auth'));return set_transient($this->evidence_key($preview_id),$record,3600);}public function preview_evidence($preview_id,$artifact_hash){$record=get_transient($this->evidence_key($preview_id));if(!is_array($record)||(int)($record['expires']??0)<time()||(int)($record['owner']??0)!==get_current_user_id())return null;if(!hash_equals((string)($record['artifact_hash']??''),(string)$artifact_hash))return null;$sig=(string)($record['signature']??'');unset($record['signature']);if(!$sig||!hash_equals(hash_hmac('sha256',Design_Core_Agent_Contract::json($record),wp_salt('auth')),$sig))return null;return (array)($record['report']??array());}
 public function audit_page($page_id,$knowledge){$page=$knowledge->page((int)$page_id);if(is_wp_error($page))return array('semantic_qa'=>'not_verified','issues'=>array());$flat=Design_Core_Agent_Knowledge::flatten_tree($page['tree']);$widgets=0;$text=0;$button=0;$issues=array();$parents=array();foreach($flat as $row){if('widget'!==($row['element_type']??''))continue;$widgets++;$w=(string)($row['widget']??'');if('text-editor'===$w){$text++;$editor=(string)($row['element']['settings']['editor']??'');if(preg_match('/<(table|article|nav)\b/i',$editor))$issues[]=array('element_id'=>$row['element_id'],'code'=>'semantic_layout_in_text');}if('button'===$w)$button++;$parents[(string)($row['parent_id']??'')][]=$w;}foreach($parents as $p=>$children){$b=count(array_filter($children,static fn($w)=>'button'===$w));if($b>=4&&$b===count($children))$issues[]=array('element_id'=>$p,'code'=>'button_navigation_cluster');}$ratio=$widgets?round($text/$widgets,4):0;if($widgets>=12&&$ratio>.45)$issues[]=array('code'=>'generic_text_ratio','ratio'=>$ratio);return array('semantic_qa'=>$issues?'warning':'pass','issues'=>$issues,'metrics'=>array('widget_count'=>$widgets,'text_editor_count'=>$text,'text_editor_ratio'=>$ratio,'button_count'=>$button));}
 private function evidence_key($preview_id){return 'dc_agent_semantic_'.hash('sha256',get_current_user_id().':'.(string)$preview_id);}
}
